-- Mom's Recipe Box: Supabase setup
-- IMPORTANT: This enables anyone on the public internet to add, edit, and delete recipes.
-- Use only if that is intentional. For a family-only site, add Supabase Auth and restrict writes.
create extension if not exists pgcrypto;
create table if not exists public.recipes (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  url text not null default '',
  cook_method text[] not null default '{}',
  effort text[] not null default '{}',
  favorites text[] not null default '{}',
  course text[] not null default '{}',
  collection text[] not null default '{}',
  cuisine text[] not null default '{}',
  ingredients text not null default '',
  instructions text not null default '',
  created_at timestamptz not null default now()
);
alter table public.recipes enable row level security;
drop policy if exists "Anyone can read recipes" on public.recipes;
drop policy if exists "Anyone can add recipes" on public.recipes;
drop policy if exists "Anyone can edit recipes" on public.recipes;
drop policy if exists "Anyone can delete recipes" on public.recipes;
create policy "Anyone can read recipes" on public.recipes for select to anon, authenticated using (true);
create policy "Anyone can add recipes" on public.recipes for insert to anon, authenticated with check (true);
create policy "Anyone can edit recipes" on public.recipes for update to anon, authenticated using (true) with check (true);
create policy "Anyone can delete recipes" on public.recipes for delete to anon, authenticated using (true);
grant select, insert, update, delete on public.recipes to anon, authenticated;

